119:     //
120:     // The mouseOut function signals to the page that the button is not being hovered.
121:     //
122:     // returns nothing
123:     private function mouseOut(event:MouseEvent): void {
124:       dispatch("mouseOut", ZeroClipboard.metaData(event));
125:     }
126: 
127:     // mouseDown
128:     //
129:     // The mouseDown function signals to the page that the button has a mouse button down.
130:     //
131:     // returns nothing
132:     private function mouseDown(event:MouseEvent): void {
133:       dispatch("mouseDown", ZeroClipboard.metaData(event));
134: 
135:       // if the clipText hasn't been set
136:       if (!clipText) {
137:         // request data from the page
138:         dispatch("dataRequested", ZeroClipboard.metaData(event));
139:       }
140:     }
